<?php
declare(strict_types=1);namespace App\Services;
use App\Config\Database;use App\Support\Reference;use PDO;use RuntimeException;
final class NotificationService{
 public static function usersForCompany(PDO$p,int$company):array{$s=$p->prepare("SELECT DISTINCT user_id FROM company_members WHERE company_id=? AND status='active' AND effective_from<=UTC_TIMESTAMP(6) AND(effective_to IS NULL OR effective_to>UTC_TIMESTAMP(6))");$s->execute([$company]);return array_map('intval',$s->fetchAll(PDO::FETCH_COLUMN));}
 public static function usersForRole(PDO$p,string$role):array{$s=$p->prepare("SELECT DISTINCT ur.user_id FROM user_roles ur JOIN roles r ON r.role_id=ur.role_id WHERE r.role_code=? AND ur.status='active' AND ur.effective_from<=UTC_TIMESTAMP(6) AND(ur.effective_to IS NULL OR ur.effective_to>UTC_TIMESTAMP(6))");$s->execute([$role]);return array_map('intval',$s->fetchAll(PDO::FETCH_COLUMN));}
 public static function send(PDO$p,array$users,string$category,string$title,string$message,?string$url,?string$entityType,?int$entityId,int$actor,string$priority='normal'):void{$users=array_values(array_unique(array_filter(array_map('intval',$users))));$n=$p->prepare("INSERT INTO notifications(notification_ref,recipient_user_id,category,priority,title,message,entity_type,entity_id_value,action_url,emitted_at,status,created_by_user_id,updated_by_user_id)VALUES(?,?,?,?,?,?,?,?,?,UTC_TIMESTAMP(6),'active',?,?)");$d=$p->prepare("INSERT INTO notification_deliveries(notification_deliverie_ref,notification_id,recipient_user_id,channel,delivery_status,delivered_at,status,created_by_user_id,updated_by_user_id)VALUES(?,?,?,'in_app','delivered',UTC_TIMESTAMP(6),'active',?,?)");foreach($users as$u){if($u===$actor)continue;$n->execute([Reference::make('NOT'),$u,$category,$priority,$title,$message,$entityType,$entityId,$url,$actor,$actor]);$id=(int)$p->lastInsertId();$d->execute([Reference::make('NDL'),$id,$u,$actor,$actor]);}}
 public static function tripEvent(PDO$p,int$trip,string$title,string$message,int$actor,string$priority='normal'):void{$s=$p->prepare("SELECT d.user_id driver_user,sh.customer_company_id,tr.carrier_company_id,tr.carrier_user_id FROM trips tr JOIN drivers d ON d.driver_id=tr.driver_id JOIN shipments sh ON sh.shipment_id=tr.shipment_id WHERE tr.trip_id=?");$s->execute([$trip]);$r=$s->fetch();if(!$r)return;$users=[(int)$r['driver_user']];if($r['carrier_user_id'])$users[]=(int)$r['carrier_user_id'];if($r['carrier_company_id'])$users=array_merge($users,self::usersForCompany($p,(int)$r['carrier_company_id']));$users=array_merge($users,self::usersForCompany($p,(int)$r['customer_company_id']),self::usersForRole($p,'MCCOLLIN_OPERATIONS'));self::send($p,$users,'shipment',$title,$message,'tracking/view.php?id='.$trip,'trip',$trip,$actor,$priority);}
 public static function inbox(int$uid):array{if(!Auth::can('NOTIFICATION_VIEW_OWN'))throw new RuntimeException('Notification permission required.');$s=Database::connection()->prepare("SELECT * FROM notifications WHERE recipient_user_id=? AND status='active' ORDER BY read_at IS NULL DESC,emitted_at DESC,notification_id DESC LIMIT 100");$s->execute([$uid]);return$s->fetchAll();}
 public static function unread(int$uid):int{if(!Auth::can('NOTIFICATION_VIEW_OWN'))return 0;try{$s=Database::connection()->prepare("SELECT COUNT(*) FROM notifications WHERE recipient_user_id=? AND read_at IS NULL AND status='active'");$s->execute([$uid]);return(int)$s->fetchColumn();}catch(\Throwable){return 0;}}
 public static function read(int$id,int$uid):void{$p=Database::connection();$p->prepare("UPDATE notifications SET read_at=COALESCE(read_at,UTC_TIMESTAMP(6)),updated_by_user_id=?,row_version=row_version+1 WHERE notification_id=? AND recipient_user_id=? AND status='active'")->execute([$uid,$id,$uid]);$p->prepare("UPDATE notification_deliveries SET read_at=COALESCE(read_at,UTC_TIMESTAMP(6)),updated_by_user_id=?,row_version=row_version+1 WHERE notification_id=? AND recipient_user_id=?")->execute([$uid,$id,$uid]);}
 public static function close(int$id,int$uid):void{self::read($id,$uid);Database::connection()->prepare("UPDATE notifications SET status='closed',updated_by_user_id=?,row_version=row_version+1 WHERE notification_id=? AND recipient_user_id=? AND status='active'")->execute([$uid,$id,$uid]);}
 public static function openTarget(int$id,int$uid):?string{$p=Database::connection();$s=$p->prepare("SELECT action_url FROM notifications WHERE notification_id=? AND recipient_user_id=? AND status='active' LIMIT 1");$s->execute([$id,$uid]);$url=$s->fetchColumn();if($url===false)throw new RuntimeException('Notification not found.');self::read($id,$uid);$url=trim((string)$url);return $url!==''?$url:null;}
 public static function sendManaged(string$type,string$target,string$title,string$message,string$priority,int$actor):void{if(!Auth::can('NOTIFICATION_MANAGE'))throw new RuntimeException('Notification management permission required.');$allowedTypes=['individual','role','all'];$roles=['MCCOLLIN_OPERATIONS','MCCOLLIN_FINANCE','SHIPPER','TRUCK_OWNER','DRIVER'];if(!in_array($type,$allowedTypes,true)||trim($title)===''||trim($message)==='')throw new RuntimeException('Recipient, title and message are required.');$p=Database::connection();$p->beginTransaction();try{if($type==='individual'){$email=strtolower(trim($target));if(!filter_var($email,FILTER_VALIDATE_EMAIL))throw new RuntimeException('Enter a valid recipient email.');$s=$p->prepare("SELECT DISTINCT u.user_id FROM users u JOIN contact_links cl ON cl.user_id=u.user_id AND cl.status='active' JOIN contacts c ON c.contact_id=cl.contact_id AND c.status='active' WHERE c.channel='email' AND c.normalized_value=? AND u.account_status='active' LIMIT 1");$s->execute([$email]);$id=$s->fetchColumn();if(!$id)throw new RuntimeException('No active account was found for that email.');$users=[(int)$id];}elseif($type==='role'){if(!in_array($target,$roles,true))throw new RuntimeException('Choose a valid role audience.');$users=self::usersForRole($p,$target);}else{$users=array_map('intval',$p->query("SELECT user_id FROM users WHERE account_status='active'")->fetchAll(PDO::FETCH_COLUMN));}self::send($p,$users,'system',trim($title),trim($message),null,null,null,$actor,$priority);$p->commit();}catch(\Throwable$e){if($p->inTransaction())$p->rollBack();throw$e;}}
 public static function broadcast(string$role,string$title,string$message,string$priority,int$actor):void{self::sendManaged($role==='ALL'?'all':'role',$role,$title,$message,$priority,$actor);}
}
